/**
 * WP Rocket's footprint: the HTML comment it appends to every page it handles, read from
 * `inc/classes/Buffer/class-cache.php` (`get_rocket_footprint`, `maybe_process_buffer`) at 3.24.1.
 *
 * The comment tells a page served from the cache apart from one just generated, without timing:
 * - a page generated by WordPress (and written to the cache by that request) ends in the comment
 *   **without** a timestamp;
 * - the cache file holds the comment **with** ` - Debug: cached@<unix time>`, so only a page served
 *   from that file — by `advanced-cache.php`, or the web server's own rewrite rules — carries one.
 *
 * `WP_ROCKET_WHITE_LABEL_FOOTPRINT` swaps the text for `Cached for great performance`; the plugin's
 * name (`WP_ROCKET_PLUGIN_NAME`) may be white-labelled too. Both forms are read.
 */

/** What a page's footprint says about how WP Rocket handled it. */
export type PageFootprint =
  /** No footprint: WP Rocket did not handle the page. */
  | { readonly kind: "none" }
  /** Generated by WordPress with WP Rocket active, not read from its cache. */
  | { readonly kind: "generated" }
  /** Served from WP Rocket's cache file, written at `cachedAt` (a Unix timestamp, the site's clock). */
  | { readonly kind: "cached"; readonly cachedAt: number };

/**
 * The footprint as the last thing in the document (trailing whitespace allowed): WP Rocket appends it
 * to the whole output buffer, so the same words anywhere else (a post quoting it) do not count.
 */
const FOOTPRINT =
  /<!-- (?:This website is like a Rocket, isn't it\? Performance optimized by [^\n]+?\. Learn more: https:\/\/wp-rocket\.me|Cached for great performance)(?: - Debug: cached@(?<cachedAt>\d+))? -->\s*$/;

/**
 * Reads WP Rocket's footprint from a page's HTML.
 *
 * @param html - the response body, as served.
 * @returns how WP Rocket handled the page.
 *
 * @example
 * ```ts
 * readFootprint("<html>…</html>\n<!-- Cached for great performance - Debug: cached@1763300000 -->");
 * // → { kind: "cached", cachedAt: 1763300000 }
 * ```
 */
export function readFootprint(html: string): PageFootprint {
  const match = FOOTPRINT.exec(html);
  if (match === null) return { kind: "none" };
  const cachedAt = match.groups?.cachedAt;
  return cachedAt === undefined
    ? { kind: "generated" }
    : { kind: "cached", cachedAt: Number(cachedAt) };
}

/**
 * A footprint in words, for an assertion's message.
 *
 * @param footprint - what {@link readFootprint} read.
 */
export function describeFootprint(footprint: PageFootprint): string {
  switch (footprint.kind) {
    case "none":
      return "no WP Rocket footprint";
    case "generated":
      return "WP Rocket's footprint of a page generated by WordPress, not served from its cache";
    case "cached":
      return `WP Rocket's footprint of a page served from its cache (cached@${String(footprint.cachedAt)})`;
  }
}

/**
 * Whether a footprint is a cached copy older than `since` — one an earlier run (a killed one, whose
 * cache files outlived its plugin) left, not one this install wrote. Pure.
 *
 * @param footprint - what {@link readFootprint} read.
 * @param since - when this install began, a Unix timestamp on the site's clock.
 */
export function isStaleFootprint(
  footprint: PageFootprint,
  since: number,
): boolean {
  return footprint.kind === "cached" && footprint.cachedAt < since;
}
